def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty)]
    sell_book = []  # [(price, arrival_time, id, qty)]
    order_map = {}  # id -> (side, price, arrival_time) for resting orders
    arrival_time = [0]  # counter for arrival times

    for order in orders:
        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_map:
                side, price, _ = order_map[cancel_id]
                del order_map[cancel_id]
                if side == 'buy':
                    buy_book[:] = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != cancel_id]
                else:
                    sell_book[:] = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != cancel_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = order[3] if order_type != 'market' else None

            current_arrival = arrival_time[0]
            arrival_time[0] += 1

            if side == 'buy':
                # Match against sell_book
                while qty > 0 and sell_book:
                    if order_type == 'market' or price >= sell_book[0][0]:
                        sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]
                        trade_qty = min(qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        qty -= trade_qty
                        if trade_qty == sell_qty:
                            sell_book.pop(0)
                            if sell_id in order_map:
                                del order_map[sell_id]
                        else:
                            sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)
                    else:
                        break

                # Add remaining qty to buy_book if limit order
                if qty > 0 and order_type == 'limit':
                    buy_book.append((price, current_arrival, order_id, qty))
                    order_map[order_id] = ('buy', price, current_arrival)
                    # Keep buy_book sorted: highest price first, then earliest arrival
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
            else:  # side == 'sell'
                # Match against buy_book
                while qty > 0 and buy_book:
                    if order_type == 'market' or price <= buy_book[0][0]:
                        buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]
                        trade_qty = min(qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        qty -= trade_qty
                        if trade_qty == buy_qty:
                            buy_book.pop(0)
                            if buy_id in order_map:
                                del order_map[buy_id]
                        else:
                            buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)
                    else:
                        break

                # Add remaining qty to sell_book if limit order
                if qty > 0 and order_type == 'limit':
                    sell_book.append((price, current_arrival, order_id, qty))
                    order_map[order_id] = ('sell', price, current_arrival)
                    # Keep sell_book sorted: lowest price first, then earliest arrival
                    sell_book.sort(key=lambda x: (x[0], x[1]))

    return trades

